const { Pool } = require('pg');
require('dotenv').config({ path: '.env.test' });

// Read DATABASE_URL from .env.test
const databaseUrl = process.env.DATABASE_URL;

if (!databaseUrl) {
  throw new Error('DATABASE_URL is not defined in .env.test');
}

// Create a connection pool
const pool = new Pool({
  connectionString: databaseUrl,
});

// Handle connection errors
pool.on('error', (err, client) => {
  console.error('Unexpected error on idle client', err.stack);
  // Close the client to prevent it from being reused
  client.release(err);
});

/**
 * Health check function to test database connectivity
 * @returns {Promise<boolean>} - True if connection is healthy, false otherwise
 */
async function isHealthy() {
  try {
    const client = await pool.connect();
    try {
      await client.query('SELECT 1');
      return true;
    } finally {
      client.release();
    }
  } catch (err) {
    console.error('Health check failed:', err.message);
    return false;
  }
}

module.exports = {
  pool,
  isHealthy,
};

'use strict';

const { Pool } = require('pg');
const fs = require('fs');
const path = require('path');

// Read .env.test file
const envTestPath = path.resolve(__dirname, '.env.test');
let envConfig = {};

if (fs.existsSync(envTestPath)) {
  const envTest = fs.readFileSync(envTestPath, 'utf-8');
  envTest.split('\n').forEach(line => {
    const match = line.match(/^([^=]+)=(.+)$/);
    if (match) {
      const key = match[1].trim();
      let value = match[2].trim();
      // Remove surrounding quotes if present
      if (/^"(.*)"$/.test(value) || /^'(.*)'$/.test(value)) {
        value = value.slice(1, -1);
      }
      envConfig[key] = value;
    }
  });
}

// Extract DATABASE_URL
const DATABASE_URL = envConfig.DATABASE_URL;

if (!DATABASE_URL) {
  console.error('DATABASE_URL is not defined in .env.test');
  process.exit(1);
}

// Create connection pool
const pool = new Pool({
  connectionString: DATABASE_URL,
});

// Handle connection errors
pool.on('error', (err, client) => {
  console.error('Unexpected error on idle client', err);
  process.exit(-1);
});

/**
 * Health check function to test database connectivity
 * @returns {Promise<boolean>} True if connection is healthy, false otherwise
 */
async function healthCheck() {
  try {
    const client = await pool.connect();
    await client.query('SELECT 1');
    client.release();
    return true;
  } catch (err) {
    console.error('Health check failed:', err.message);
    return false;
  }
}

module.exports = {
  pool,
  healthCheck,
};

